from hashlib import sha3_512
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
from decimal import Decimal, getcontext
import base64, sys, zlib, marshal, importlib.util, platform, hmac, tempfile, os, gc
getcontext().prec = 50

def logistic_map(x, r):
    x = Decimal(str(x)); r = Decimal(str(r))
    return r * x * (Decimal('1') - x)

def henon_map(x, y, a, b):
    x = Decimal(str(x)); y = Decimal(str(y)); a = Decimal(str(a)); b = Decimal(str(b))
    xn = Decimal('1') - a * x * x + y
    yn = b * x
    return xn, yn

def aes_dec(enc, key):
    try:
        nonce, tag, ct = enc[:16], enc[16:32], enc[32:]
        cipher = AES.new(key[:32], AES.MODE_GCM, nonce=nonce)
        return unpad(cipher.decrypt_and_verify(ct, tag), AES.block_size)
    except: return None
def unshuffle(data, idx):
    if len(data) != len(idx): return None
    orig = bytearray(len(data))
    for i, pos in enumerate(idx): orig[i] = data[pos]
    return orig

def gen_key(salt, seed):
    return sha3_512(salt + str(seed).encode()).digest()

def decrypt_main(data):
    salt = data[:32]
    orig_len = int.from_bytes(data[32:40], 'big')
    seed = int.from_bytes(data[40:56], 'big')
    r1 = Decimal(int.from_bytes(data[56:60], 'big')) / 10000
    r2 = Decimal(int.from_bytes(data[60:64], 'big')) / 10000
    a = Decimal(int.from_bytes(data[64:68], 'big')) / 10000
    b = Decimal(int.from_bytes(data[68:72], 'big')) / 10000
    idx_len = int.from_bytes(data[72:76], 'big')
    idx_b64 = data[76:76+idx_len]
    encrypted = data[76+idx_len:]
    idx_bytes = base64.b64decode(idx_b64)
    indices = [int.from_bytes(idx_bytes[i:i+4], 'big') for i in range(0, len(idx_bytes), 4)]
    key = gen_key(salt, seed)
    dec_shuf = aes_dec(encrypted, key)
    if not dec_shuf: return None
    dec_perm = unshuffle(dec_shuf, indices)
    if not dec_perm: return None
    skey = int.from_bytes(key[:8], 'big')
    lx1 = Decimal(max(min((skey % 1000000) / 1000000.0, 0.9), 0.1))
    lx2 = Decimal(max(min((skey % 2000000) / 2000000.0, 0.9), 0.1))
    hx = Decimal(max(min((skey % 3000000) / 3000000.0, 0.9), 0.1))
    hy = Decimal(max(min((skey % 4000000) / 4000000.0, 0.9), 0.1))
    res = bytearray()
    for i, bv in enumerate(dec_perm):
        lx1 = logistic_map(lx1, r1)
        lx2 = logistic_map(lx2, r2)
        hx, hy = henon_map(hx, hy, a, b)
        lx1 = max(min(lx1, Decimal('0.9')), Decimal('0.1'))
        lx2 = max(min(lx2, Decimal('0.9')), Decimal('0.1'))
        hx = max(min(hx, Decimal('0.9')), Decimal('0.1'))
        ky = key[i % len(key)]
        chaos = (int(lx1 * 255) + int(lx2 * 255) + int(hx * 255)) % 256
        res.append(bv ^ (chaos ^ ky))
    if len(res) != orig_len: return None
    return res
data_b64 = ""
key2 = base64.b64decode("+WorUFRnvEK0TgLeuSI2t0P0I+CTCYdL4X0EdNd6i/Q=")
enc_data = aes_dec(base64.b64decode(data_b64), key2)
if enc_data is None: sys.exit(1)
dec_data = decrypt_main(enc_data)
if dec_data is None: sys.exit(1)
code = zlib.decompress(dec_data).decode('utf-8')
exec(compile(code, '<memory>', 'exec'), globals())
